local R=dofile('tests/kernel_spotlights_harness.lua')
local n=0
local function case(name,fn)R.menuCase(name,fn);n=n+1 end
case('root/settings parent',function(r)r.menu.openSpotlightsMenu();assert(r.last.menu=='forge_core_server_settings'and #r.last.options==4)end)
case('settings route',function(r)r.menu.openServerSettingsMenu();r.select(12);assert(r.last.id=='forge_core_spotlights')end)
case('fetch refused',function(r)r.rpcHook=function()return false,'no_permission'end;r.menu.openSpotlightsMenu()end)
case('fetch malformed',function(r)r.rpcHook=function()return true,false end;r.menu.openSpotlightsMenu();assert(#r.spotlights.lights==0)end)
case('fetch synchronizes runtime immediately',function(r)r.menu.openSpotlightsMenu();assert(#r.spotlights.lights==1 and r.spotlights.enabled)end)
case('create group cancel',function(r)r.menu.openSpotlightsMenu();r.select(1)end)
case('create group save',function(r)r.inputs={{'New'}};r.menu.openSpotlightsMenu();r.select(1);r.runTimers()end)
case('create group refused',function(r)r.inputs={{'New'}};r.menu.openSpotlightsMenu();r.rpcHook=function()return false,'no_permission'end;r.select(1);r.runTimers()end)
case('nonempty group cannot delete',function(r)r.menu.openSpotlightsGroup('1','fallback');assert(r.last.title=='Group A'and r.last.id=='forge_core_spotlights_group_1'and #r.last.options==5)end)
case('group count controls disable',function(r)r.payload.groups[1].count=1;r.menu.openSpotlightsGroup(1,'A');assert(r.last.options[3].disabled)end)
case('unknown group fallback',function(r)r.menu.openSpotlightsGroup(99,'Fallback');assert(r.last.title=='Fallback'and #r.last.options==4)end)
case('rename cancel',function(r)r.menu.openSpotlightsGroup(1,'A');r.select(2)end)
case('rename save',function(r)r.inputs={{'New'}};r.menu.openSpotlightsGroup(1,'A');r.select(2);r.runTimers()end)
case('rename refused',function(r)r.inputs={{'New'}};r.menu.openSpotlightsGroup(1,'A');r.rpcHook=function()return false,'save_failed'end;r.select(2);r.runTimers()end)
case('delete group confirm',function(r)r.alerts={'confirm'};r.menu.openSpotlightsGroup(2,'B');r.select(3);r.runTimers()end)
case('delete group cancel',function(r)r.alerts={'cancel'};r.menu.openSpotlightsGroup(2,'B');r.select(3)end)
case('delete group refused',function(r)r.alerts={'confirm'};r.menu.openSpotlightsGroup(2,'B');r.rpcHook=function()return false,'group_not_empty'end;r.select(3);r.runTimers()end)
case('missing light back to root',function(r)r.menu.openSpotlightActions(99);assert(r.last.id=='forge_core_spotlights')end)
case('actions parent',function(r)r.menu.openSpotlightActions(1);assert(r.last.menu=='forge_core_spotlights_group_1'and #r.last.options==4)end)
case('edit data cancel',function(r)r.menu.openSpotlightActions(1);r.select(1)end)
case('edit data save/palette',function(r)r.inputHook=function(_,fields)assert(fields[3].type=='color'and fields[3].default=='#0a141e');return{'New','false','#abc',90,2,3,4}end;r.menu.openSpotlightActions(1);r.select(1);r.runTimers()end)
case('edit data refused',function(r)r.inputs={{'X','true','#123',1,2,3,4}};r.menu.openSpotlightActions(1);r.rpcHook=function()return false,'save_failed'end;r.select(1);r.runTimers()end)
case('toggle off',function(r)r.menu.openSpotlightActions(1);r.select(3);r.runTimers()end)
case('toggle on string false',function(r)r.payload.lights[1].enabled='false';r.menu.openSpotlightActions(1);r.select(3);r.runTimers()end)
case('toggle refused',function(r)r.menu.openSpotlightActions(1);r.rpcHook=function()return false,'no_permission'end;r.select(3);r.runTimers()end)
case('toggle response applied immediately',function(r)r.menu.openSpotlightActions(1);r.rpcHook=function()local p=R.seed();p.lights[1].enabled=false;return true,p end;r.select(3);assert(not r.spotlights.lights[1].enabled)end)
case('malformed response ignored',function(r)r.menu.openSpotlightActions(1);r.rpcHook=function()return true,{lights=false}end;r.select(3);assert(#r.spotlights.lights==1)end)
case('delete light confirm',function(r)r.alerts={'confirm'};r.menu.openSpotlightActions(1);r.select(4);r.runTimers()end)
case('delete light cancel',function(r)r.alerts={'cancel'};r.menu.openSpotlightActions(1);r.select(4)end)
case('delete light refused',function(r)r.alerts={'confirm'};r.menu.openSpotlightActions(1);r.rpcHook=function()return false,'save_failed'end;r.select(4);r.runTimers()end)
case('fine tune confirm',function(r)r.menu.openSpotlightActions(1);local co=r.run(function()r.select(2)end);r.finish(co);r.runTimers()end)
case('fine tune cancel',function(r)r.menu.openSpotlightActions(1);local co=r.run(function()r.select(2)end);r.finish(co,false);r.runTimers()end)
case('fine tune server refused',function(r)r.menu.openSpotlightActions(1);local co=r.run(function()r.select(2)end);r.rpcHook=function()return false,'save_failed'end;r.finish(co);r.runTimers()end)
case('fine tune unavailable error',function(r)r.spotlights.editLight=function()return false,'fixture-unavailable'end;r.menu.openSpotlightActions(1);r.select(2);r.runTimers()end)
case('create light confirm',function(r)r.inputs={{'New','true','#123',90,2,3,4}};r.menu.openSpotlightsGroup(1,'A');local co=r.run(function()r.select(1)end);r.just={[38]=true};r.resume(co);r.resume(co);r.finish(co);r.runTimers()end)
case('create light origin canceled',function(r)r.menu.openSpotlightsGroup(1,'A');local co=r.run(function()r.select(1)end);r.just={[177]=true};r.resume(co);r.runTimers()end)
case('create light refused',function(r)r.inputs={{'New','true','#123',90,2,3,4}};r.menu.openSpotlightsGroup(1,'A');local co=r.run(function()r.select(1)end);r.just={[38]=true};r.resume(co);r.resume(co);r.rpcHook=function()return false,'no_permission'end;r.finish(co);r.runTimers()end)
case('create light busy',function(r)r.menu.openSpotlightsGroup(1,'A');r.spotlights.editorActive=true;r.select(1);r.runTimers()end)
case('create unavailable',function(r)r.library.raycast=nil;r.menu.openSpotlightsGroup(1,'A');r.select(1);r.runTimers()end)
case('sorted lights',function(r)r.payload.lights[2]={id=5,groupId=1,name='Five'};r.payload.lights[3]={id=2,groupId=1,name='Two'};r.menu.openSpotlightsGroup(1,'A');assert(r.last.options[6].title=='[2] Two'and r.last.options[7].title=='[5] Five')end)
case('old menu snapshot applies complete payload',function(r)r.menu.openSpotlightActions(1);r.payload.lights[1].name='Updated later';r.select(3);r.runTimers()end)
case('RPC exception keeps callback error',function(r)r.menu.openSpotlightActions(1);r.rpcHook=function()error('fixture-rpc',0)end;assert(not pcall(r.select,3))end)
print('PASS spotlights menu differentials '..n)
